<?php declare(strict_types=1);require_once __DIR__.'/includes/bootstrap.php';$lh_page_title='Search';$q=trim((string)($_GET['q']??''));$results=[];if($q!==''){try{$s='%'.$q.'%';$st=$db->prepare('SELECT id,title,slug,description FROM learning_courses WHERE enabled=1 AND (title LIKE ? OR description LIKE ?) ORDER BY featured DESC,title LIMIT 50');$st->execute([$s,$s]);$results=$st->fetchAll(PDO::FETCH_ASSOC);}catch(Throwable){}}include __DIR__.'/includes/header.php';include __DIR__.'/includes/navbar.php';?><div class="container py-5"><h1 class="fw-bold">Search Learning Hub</h1><form class="row g-2 mt-3"><div class="col-sm-9"><input class="form-control form-control-lg" name="q" value="<?=lh_h($q)?>" placeholder="Search courses..."></div><div class="col-sm-3"><button class="btn btn-primary btn-lg w-100">Search</button></div></form><div class="vstack gap-2 mt-4"><?php foreach($results as $r):?><a class="lh-card p-4 text-decoration-none" href="/learning-hub/course.php?slug=<?=rawurlencode($r['slug'])?>"><h2 class="h5 mb-1"><?=lh_h($r['title'])?></h2><p class="small text-secondary mb-0"><?=lh_h($r['description']??'')?></p></a><?php endforeach;if($q!==''&&!$results):?><div class="alert alert-light border">No matching courses found.</div><?php endif;?></div></div><?php include __DIR__.'/includes/footer.php';?>